// Normalize & validate: clean up raw form data into a consistent lead record.
const PERSONAL_DOMAINS = [
  'gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com',
  'live.com', 'icloud.com', 'aol.com', 'proton.me', 'protonmail.com',
  'gmx.de', 'gmx.net', 'web.de', 't-online.de'
];
const clean = (v) => String(v ?? '').trim();

return $input.all().map((item) => {
  const b = item.json.body ?? item.json; // webhook puts form data in "body"
  const email = clean(b.email).toLowerCase();
  const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  const domain = emailValid ? email.split('@')[1] : null;

  return {
    json: {
      email,
      email_valid: emailValid,
      domain,
      is_personal_email: domain ? PERSONAL_DOMAINS.includes(domain) : false,
      first_name: clean(b.first_name),
      last_name: clean(b.last_name),
      job_title: clean(b.job_title),
      company: clean(b.company),
      company_size: clean(b.company_size) || 'unknown',
      industry: clean(b.industry) || 'unknown',
      use_case: clean(b.use_case),
      timeline: clean(b.timeline) || 'unknown',
      source: clean(b.source) || 'website_form',
      received_at: new Date().toISOString(),
    },
  };
});

// Score lead: fit (who they are, max 60) + intent (what they want, max 40).
// Every point is logged in score_breakdown so sales can see WHY a lead scored as it did.
const SIZE_POINTS = { '5000+': 25, '1001-5000': 20, '201-1000': 12, '51-200': 6, '1-50': 2 };
const PRIORITY_INDUSTRIES = [
  'financial services', 'insurance', 'healthcare & pharma', 'manufacturing',
  'retail & e-commerce', 'energy & utilities', 'telecommunications'
];
const USE_CASE_SIGNALS = {
  'prediction task': /predict|forecast|classif|regression|estimat/,
  'known tabular use case': /churn|fraud|risk|credit|demand|pricing|maintenance|claims|default/,
  'tabular data': /tabular|table|spreadsheet|rows|csv|structured data|features/,
  'current ML stack': /xgboost|gradient boost|lightgbm|catboost|automl|random forest/,
};
const TIMELINE_POINTS = { 'within 3 months': 15, '3-6 months': 8, 'exploring': 2 };

return $input.all().map((item) => {
  const lead = item.json;
  const breakdown = [];
  let fit = 0, intent = 0;

  if (!lead.email_valid) {
    return { json: { ...lead, score: 0, tier: 'invalid', score_breakdown: ['invalid email'] } };
  }

  // --- Fit ---
  const sizePts = SIZE_POINTS[lead.company_size] ?? 0;
  fit += sizePts; breakdown.push(`+${sizePts} company size (${lead.company_size})`);

  const industry = lead.industry.toLowerCase();
  const indPts = PRIORITY_INDUSTRIES.includes(industry) ? 15 : industry === 'unknown' ? 0 : 5;
  fit += indPts; breakdown.push(`+${indPts} industry (${lead.industry})`);

  const title = lead.job_title.toLowerCase();
  if (/head|director|vp|vice president|chief|cdo|cto|lead|principal/.test(title)) {
    fit += 10; breakdown.push('+10 senior role');
  }
  if (/data|machine learning|\bml\b|analytics|\bai\b|scientist|quant/.test(title)) {
    fit += 10; breakdown.push('+10 data/ML role');
  }

  // --- Intent ---
  const useCase = lead.use_case.toLowerCase();
  if (useCase.length >= 20) {
    for (const [label, pattern] of Object.entries(USE_CASE_SIGNALS)) {
      if (pattern.test(useCase)) { intent += 6; breakdown.push(`+6 ${label}`); }
    }
    intent = Math.min(intent, 25);
  } else {
    breakdown.push('+0 use case too short to assess');
  }
  const tlPts = TIMELINE_POINTS[lead.timeline.toLowerCase()] ?? 0;
  intent += tlPts; breakdown.push(`+${tlPts} timeline (${lead.timeline})`);

  // --- Penalties ---
  let score = fit + intent;
  if (lead.is_personal_email) { score -= 15; breakdown.push('-15 personal email domain'); }
  score = Math.max(0, Math.min(100, score));

  const tier = score >= 75 ? 'hot' : score >= 35 ? 'warm' : 'cold';
  return { json: { ...lead, fit_score: fit, intent_score: intent, score, tier, score_breakdown: breakdown } };
});

// Map the scored lead onto HubSpot property names.
// Empty values are dropped so a sparse resubmission never blanks out data already in HubSpot.
return $input.all().map((item) => {
  const l = item.json;
  const raw = {
    email: l.email,
    firstname: l.first_name,
    lastname: l.last_name,
    jobtitle: l.job_title,
    company: l.company,
    lead_score: String(l.score),
    lead_tier: l.tier,
    score_breakdown: (l.score_breakdown || []).join('\n'),
    lead_source_form: l.source,
  };
  const props = Object.fromEntries(
    Object.entries(raw).filter(([, v]) => v !== '' && v !== null && v !== undefined)
  );
  return { json: { ...l, hubspot_properties: props } };
});

// Final response for the webhook caller: the scored lead plus what happened in HubSpot.
const lead = $('Score Lead').first().json;
let hubspot = { action: 'skipped', reason: 'invalid email' };

if (lead.tier !== 'invalid') {
  const search = $('Search Contact').first().json;
  hubspot = {
    action: search.total > 0 ? 'updated' : 'created',
    contact_id: $input.first().json.id,
  };
}
return [{ json: { ...lead, hubspot } }];

// Build the Slack message for hot and warm leads.
// Find your Hub ID in HubSpot (account menu, top right) and paste it below to get a working "Open in HubSpot" link.
const PORTAL_ID = '149491548';

const l = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const name = esc(`${l.first_name} ${l.last_name}`.trim() || l.email);
const where = esc([l.job_title, l.company].filter(Boolean).join(' @ '));
const hasLink = l.hubspot?.contact_id && PORTAL_ID !== 'YOUR_HUBSPOT_PORTAL_ID';
const link = hasLink
  ? `\n<https://app.hubspot.com/contacts/${PORTAL_ID}/record/0-1/${l.hubspot.contact_id}|Open in HubSpot>`
  : '';

let text = '';
if (l.tier === 'hot') {
  const reasons = (l.score_breakdown || []).map((r) => `• ${esc(r)}`).join('\n');
  const useCase = esc(l.use_case).slice(0, 300);
  text =
    `:fire: *HOT lead: ${name}*${where ? `, ${where}` : ''}\n` +
    `*Score:* ${l.score}/100 (fit ${l.fit_score}, intent ${l.intent_score})\n` +
    `*Use case:* ${useCase || 'not provided'}\n` +
    `*Why it scored this way:*\n${reasons}` +
    link;
} else if (l.tier === 'warm') {
  text =
    `:sunny: Warm lead: *${name}*${where ? `, ${where}` : ''}. ` +
    `Score ${l.score}/100.${link}`;
}
return [{ json: { ...l, slack_text: text } }];
